import { describe, it, expect } from 'vitest';
import { Sex } from '$lib/ble/protocol';
import { calcFullBodyComposition, type FullBodyComposition } from './vendor-bia';

// Golden reference values generated by running the validated Python reference
// (poc/cf632ble/vendor_bia.py `calc_full_body_composition`) — the port must match it exactly.
// The male case is also the hardware-confirmed one: the vendor app shows 21.4% for these inputs
// (RE-NOTES §18).

function body(input: Parameters<typeof calcFullBodyComposition>[0]): FullBodyComposition {
	const res = calcFullBodyComposition(input);
	if (!res.ok) throw new Error(`unexpected range errors: ${res.errors.join('; ')}`);
	return res.body;
}

describe('calcFullBodyComposition — male 173cm/72.2kg/37y (hardware-confirmed, RE-NOTES §18)', () => {
	const b = body({
		weightKg: 72.2,
		heightCm: 173,
		age: 37,
		sex: Sex.MALE,
		z50khzOhm: 448,
		z100khzOhm: 418
	});

	it('matches the vendor app: body fat 21.4%', () => {
		expect(b.bodyFatRatePercent).toBeCloseTo(21.4, 6);
	});

	it('reproduces every metric from the Python reference', () => {
		expect(b.bmi).toBeCloseTo(24.1, 6);
		expect(b.bodyFatKg).toBeCloseTo(15.4, 6);
		expect(b.fatFreeMassKg).toBeCloseTo(56.8, 6);
		expect(b.boneKg).toBeCloseTo(2.8, 6);
		expect(b.muscleKg).toBeCloseTo(54.0, 6);
		expect(b.muscleRatePercent).toBeCloseTo(74.7, 6);
		expect(b.skeletalMuscleKg).toBeCloseTo(29.6, 6);
		expect(b.waterRatePercent).toBeCloseTo(53.9, 6);
		expect(b.proteinRatePercent).toBeCloseTo(14.5, 6);
		expect(b.subcutaneousFatRatePercent).toBeCloseTo(18.7, 6);
		expect(b.subcutaneousFatKg).toBeCloseTo(13.5, 6);
		expect(b.bmrKcal).toBe(1497);
		expect(b.vfal).toBe(11);
		expect(b.idealWeightKg).toBeCloseTo(65.8, 6);
		expect(b.bodyAge).toBe(38);
		expect(b.bodyScore).toBe(92);
		expect(b.bodyType).toBe(8);
	});

	it('reproduces every per-metric Level (RE-NOTES §21)', () => {
		expect(b.bmiLevel.label).toBe('Normal');
		expect(b.bodyFatRateLevel.label).toBe('Standard+');
		expect(b.bmrLevel.label).toBe('Under');
		expect(b.vfalLevel.label).toBe('Alert');
		expect(b.boneLevel.label).toBe('Standard');
		expect(b.muscleLevel.label).toBe('Standard');
		expect(b.waterLevel.label).toBe('Under');
		expect(b.proteinLevel.label).toBe('Under');
		expect(b.skeletalMuscleLevel.label).toBe('Standard');
		expect(b.subcutaneousFatLevel.label).toBe('Over');
	});
});

describe('calcFullBodyComposition — female 165cm/60kg/29y', () => {
	const b = body({
		weightKg: 60.0,
		heightCm: 165,
		age: 29,
		sex: Sex.FEMALE,
		z50khzOhm: 520,
		z100khzOhm: 495
	});

	it('matches the Python reference', () => {
		expect(b.bmi).toBeCloseTo(22.0, 6);
		expect(b.bodyFatRatePercent).toBeCloseTo(28.2, 6);
		expect(b.bodyFatKg).toBeCloseTo(16.9, 6);
		expect(b.muscleRatePercent).toBeCloseTo(67.8, 6);
		expect(b.waterRatePercent).toBeCloseTo(49.2, 6);
		expect(b.bmrKcal).toBe(1232);
		expect(b.vfal).toBe(4);
		expect(b.bodyType).toBe(9);
		expect(b.muscleLevel.label).toBe('Excellent');
		expect(b.waterLevel.label).toBe('Standard'); // sex-dependent band (RE-NOTES §21)
	});
});

describe('calcFullBodyComposition — male athlete 180cm/80kg/25y', () => {
	const b = body({
		weightKg: 80.0,
		heightCm: 180,
		age: 25,
		sex: Sex.MALE,
		z50khzOhm: 400,
		z100khzOhm: 380,
		athlete: true
	});

	it('applies the athlete adjustments (matches Python reference)', () => {
		expect(b.bodyFatRatePercent).toBeCloseTo(15.9, 6);
		expect(b.boneKg).toBeCloseTo(3.4, 6);
		expect(b.skeletalMuscleKg).toBeCloseTo(35.7, 6);
		expect(b.bmrKcal).toBe(1841);
		expect(b.bodyScore).toBe(97);
		expect(b.bmrLevel.label).toBe('Standard');
		expect(b.boneLevel.label).toBe('Excellent');
	});
});

describe('calcFullBodyComposition — out-of-range input', () => {
	it('returns range errors (native lib would reject) instead of a result', () => {
		const res = calcFullBodyComposition({
			weightKg: 72.0,
			heightCm: 173,
			age: 37,
			sex: Sex.MALE,
			z50khzOhm: 50, // below the 200-1200 ohm validated range
			z100khzOhm: 418
		});
		expect(res.ok).toBe(false);
		if (!res.ok) expect(res.errors.join()).toMatch(/z50khz/);
	});
});
